// Original geometry additions on the reviewed rigs; existing facial/eye maps are retained.
export function seatWizardHat(B,meshes){
 let shifted=0;for(const m of meshes){if(!m.material?.name.includes('weathered grey woven wool'))continue;const source=m.getVerticesData(B.VertexBuffer.PositionKind);if(!source)continue;const p=source.slice(),indices=[];let changed=false;for(let i=1;i<p.length;i+=3)if(p[i]>1.8){p[i]-=.065;indices.push(i);shifted++;changed=true;}if(changed){m.makeGeometryUnique();m.setVerticesData(B.VertexBuffer.PositionKind,p);if(m.morphTargetManager)for(let ti=0;ti<m.morphTargetManager.numTargets;ti++){const target=m.morphTargetManager.getTarget(ti),positions=target.getPositions();if(positions){const updated=positions.slice();for(const i of indices)updated[i]-=.065;target.setPositions(updated);}}m.refreshBoundingInfo();}}
 return shifted;
}
export function addCurlyHair(B,scene,{id,role,head,meshes}){
 if(role==='gandalf')return null;
 const hair=meshes.find(m=>{if(!m.name.includes('wardrobe')||!m.material?.name.includes('MI_Hair'))return false;const b=m.getBoundingInfo().boundingBox;return b.maximumWorld.y-b.minimumWorld.y>.09&&b.minimumWorld.y>meshes.find(v=>v.name.includes('anatomical face'))?.getBoundingInfo().boundingBox.minimumWorld.y;});
 if(!hair)return null;
 hair.computeWorldMatrix(true);const bounds=hair.getBoundingInfo().boundingBox,lo=bounds.minimumWorld,hi=bounds.maximumWorld,cx=(lo.x+hi.x)/2,cz=(lo.z+hi.z)/2,rx=(hi.x-lo.x)*.5,rz=(hi.z-lo.z)*.5,height=hi.y-lo.y;
 let mat=scene.getMaterialByName('soft storybook curls '+role);if(!mat){mat=new B.StandardMaterial('soft storybook curls '+role,scene);mat.diffuseColor=B.Color3.FromHexString(role==='bilbo'?'#756355':role==='sam'?'#715139':'#3b291e');mat.specularColor.set(.07,.055,.04);mat.specularPower=18;}
 const parts=[];for(let i=0;i<31;i++){const t=.48+.5*(i+.5)/31,r=Math.sqrt(1-t*t),a=i*2.399,x=cx+rx*r*Math.cos(a),z=cz+rz*r*Math.sin(a),y=lo.y+height*t,path=[];for(let j=0;j<=12;j++){const angle=j/12*Math.PI*2.8;path.push(new B.Vector3(x+Math.cos(angle)*.018,y+Math.sin(angle*.5)*.008,z+Math.sin(angle)*.018));}const m=B.MeshBuilder.CreateTube('authored soft hair curl',{path,radius:.0065,tessellation:5,cap:B.Mesh.CAP_ALL},scene);m.material=mat;parts.push(m);}
 const curls=B.Mesh.MergeMeshes(parts,true,true);curls.name=id+' head-following curly hair';head.computeWorldMatrix(true);const inverse=head.getWorldMatrix().clone().invert(),p=curls.getVerticesData(B.VertexBuffer.PositionKind),n=curls.getVerticesData(B.VertexBuffer.NormalKind);for(let i=0;i<p.length;i+=3){const v=B.Vector3.TransformCoordinates(new B.Vector3(p[i],p[i+1],p[i+2]),inverse);p[i]=v.x;p[i+1]=v.y;p[i+2]=v.z;const normal=B.Vector3.TransformNormal(new B.Vector3(n[i],n[i+1],n[i+2]),inverse).normalize();n[i]=normal.x;n[i+1]=normal.y;n[i+2]=normal.z;}curls.setVerticesData(B.VertexBuffer.PositionKind,p);curls.setVerticesData(B.VertexBuffer.NormalKind,n);curls.parent=head;curls.isPickable=false;curls.receiveShadows=true;curls.refreshBoundingInfo();return curls;
}
